from collections import Counter

class Solution:
    def largestComponentSize(self, nums: list[int]) -> int:
        parent = {}
        def find(x: int) -> int:
            if parent.setdefault(x, x) != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x: int, y: int):
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[rx] = ry
        for num in nums:
            d = 2
            val = num
            while d * d <= val:
                if val % d == 0:
                    union(num, d)
                    while val % d == 0:
                        val //= d
                d += 1
