class Solution {
public:
    int largestComponentSize(vector<int>& nums) {
        int max_val = 0;
        for (int x : nums) max_val = max(max_val, x);
        vector<int> parent(max_val + 1);
        iota(parent.begin(), parent.end(), 0);

        auto find = [&](auto& self, int x) -> int {
            if (parent[x] != x) parent[x] = self(self, parent[x]);
            return parent[x];
        };
        auto unite = [&](int x, int y) {
            int rx = find(find, x), ry = find(find, y);
            if (rx != ry) parent[rx] = ry;
        };

        for (int num : nums) {
            int val = num;
            for (int d = 2; d * d <= val; ++d) {
                if (val % d == 0) {
                    unite(num, d);
                    while (val % d == 0) val /= d;
                }
            }
            if (val > 1) unite(num, val);
        }

        unordered_map<int, int> counts;
        int max_size = 0;
        for (int num : nums) {
            int root = find(find, num);
            max_size = max(max_size, ++counts[root]);
        }
        return max_size;
    }
};

class Solution {
    private int[] parent;

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    private void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) {
            parent[rx] = ry;
        }
    }

    public int largestComponentSize(int[] nums) {
        int maxVal = 0;
        for (int x : nums) maxVal = Math.max(maxVal, x);
        parent = new int[maxVal + 1];
        for (int i = 0; i <= maxVal; i++) parent[i] = i;

        for (int num : nums) {
            int val = num;
            for (int d = 2; d * d <= val; d++) {
                if (val % d == 0) {
                    union(num, d);
                    while (val % d == 0) val /= d;
                }
            }
            if (val > 1) union(num, val);
        }

        Map<Integer, Integer> counts = new HashMap<>();
        int maxSize = 0;
        for (int num : nums) {
            int root = find(num);
            int count = counts.getOrDefault(root, 0) + 1;
            counts.put(root, count);
            maxSize = Math.max(maxSize, count);
        }
        return maxSize;
    }
}

var largestComponentSize = function(nums) {
    let maxVal = 0;
    for (const x of nums) if (x > maxVal) maxVal = x;
    const parent = new Int32Array(maxVal + 1);
    for (let i = 0; i <= maxVal; i++) parent[i] = i;

    const find = (x) => {
        if (parent[x] !== x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    };
    const union = (x, y) => {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent[rx] = ry;
    };

    for (const num of nums) {
        let val = num;
        for (let d = 2; d * d <= val; d++) {
            if (val % d === 0) {
                union(num, d);
                while (val % d === 0) val = Math.floor(val / d);
            }
        }
        if (val > 1) union(num, val);
    }

    const counts = new Map();
    let maxSize = 0;
    for (const num of nums) {
        const root = find(num);
        const count = (counts.get(root) || 0) + 1;
        counts.set(root, count);
        if (count > maxSize) maxSize = count;
    }
    return maxSize;
};
